// GENERATED by `node pipelines/books/export-weave-rules.ts` from pipelines/books/lib/split-forms.ts, word for word. Don't edit by hand: change those, generate again, and land it.
// Two ways a partly known woven sentence teaches something false, found from a weave's own data (no model), so the
// bar counts them every time rather than when a judge's sample banks happen to show them (63, 6 Nov: "an auxiliary goes
// with its verb: both English or the target form alone, never one of each; a clitic only goes beside a target-language
// verb, never after an English one"):
//
//   split-form     an English word glossed with no lemma (so it always stays English) whose meaning a target word
//                  carries together with another English word that does show: the shown word's gloss is the very
//                  natural word whose m entry lists both as its sources. Once that lemma is known, the English word
//                  stands beside a form that already says it ("will" + a future form, "did" + a past form, "there" +
//                  an existential verb). A run covered by an idiom upgrade (u) shows as one and isn't counted.
//   pronoun-alone  an English object pronoun glossed with its own lemma right after an English verb glossed with
//                  another lemma, so the pronoun can show beside the English verb ("gave" + a clitic). Only a
//                  language's own object pronouns count where the registry lists them (objectPronouns), and the verb
//                  is told by the registry's verbLemma pattern where it has one.
//
// Pure, so test.ts runs it on made-up sentences.

export interface SplitFinding {
  x: number;
  kind: "word:split-form" | "word:pronoun-alone";
  english: string;
  gloss: [string, string | null];
  fix: string;
  why: string;
}

export interface SplitRules {
  /** The target language's object pronouns that go with a verb (lowercase); without them, any lemma'd gloss counts. */
  objectPronouns?: string[];
  /** A regex source a verb's lemma matches in the target language; without it, the English word before decides. */
  verbLemma?: string;
}

const AUX = new Set(["will", "would", "shall", "should", "did", "do", "does", "have", "has", "had", "am", "is", "are", "was", "were", "be", "been", "being", "to", "can", "could", "may", "might", "must", "there", "'ll", "'d", "’ll", "’d"]);
const OBJECT = new Set(["her", "him", "it", "them", "me", "you", "us", "himself", "herself", "itself", "themselves", "myself", "yourself", "yourselves", "ourselves"]);
const NOT_A_VERB = new Set(["in", "to", "at", "on", "for", "with", "of", "from", "by", "about", "into", "over", "under", "after", "before", "like", "than", "upon", "through", "towards", "toward", "round", "near", "behind", "beyond", "across", "along", "around", "among", "against", "below", "beneath", "beside", "besides", "between", "past", "since", "until", "till", "within", "without", "onto", "inside", "outside", "throughout", "underneath", "up", "down", "off", "out", "and", "or", "but", "nor", "as", "if", "that", "when", "while", "the", "a", "an", "all", "both"]);
const bare = (s: string) => String(s).toLowerCase().replace(/^[^\p{L}'’]+|[^\p{L}'’]+$/gu, "");
const plain = (s: string) => bare(s).normalize("NFC");

/** Every split form and pronoun alone in the given sentences (all of them by default). */
export function splitForms(book: { words: string[] }, weave: { sentences: any[] }, rules: SplitRules = {}, xs?: number[]): SplitFinding[] {
  const out: SplitFinding[] = [];
  const pronouns = rules.objectPronouns ? new Set(rules.objectPronouns.map(plain)) : null;
  const verb = rules.verbLemma ? new RegExp(rules.verbLemma, "u") : null;
  for (const x of xs ?? weave.sentences.map((_, i) => i)) {
    const s = weave.sentences[x];
    if (!s) continue;
    const words = book.words.slice(s.s, s.e);
    const t: [string, string | null][] = s.t;
    const covered = (a: number, b: number) => (s.u ?? []).some(([k, len]: [number, number]) => a >= k && a < k + len && b >= k && b < k + len);
    const seen = new Set<string>();
    for (const [target, , sources, lemma] of s.m ?? []) {
      if (!lemma) continue;
      const stays = sources.filter((k: number) => t[k] && t[k][1] === null && AUX.has(bare(words[k] ?? "")));
      // The shown word: its gloss is this very natural word (same lemma, same form), so it carries what the other says.
      const shows = sources.filter((k: number) => t[k] && t[k][1] === lemma && plain(t[k][0]).split(/\s+/).includes(plain(target)));
      for (const k of stays) for (const j of shows) {
        if (covered(k, j) || seen.has(`${k}|${j}`)) continue;
        seen.add(`${k}|${j}`);
        out.push({
          x,
          kind: "word:split-form",
          english: words[k]!,
          gloss: t[k]!,
          fix: `one group with ${JSON.stringify(words[j])}: the lemma ${JSON.stringify(lemma)} on both, and a u over the run`,
          why: `once ${JSON.stringify(lemma)} is known, ${JSON.stringify(words[k])} stays English beside ${JSON.stringify(t[j]![0])}, which already says it`,
        });
      }
    }
    t.forEach(([target, lemma], j) => {
      if (!lemma || j === 0 || !OBJECT.has(bare(words[j] ?? ""))) return;
      if (pronouns && !pronouns.has(plain(target))) return;
      const before = words[j - 1] ?? "";
      const [, verbLemma] = t[j - 1] ?? [];
      if (!verbLemma || verbLemma === lemma || covered(j - 1, j)) return;
      if (NOT_A_VERB.has(bare(before)) || /[^\p{L}'’]$/u.test(before)) return;
      if (verb && !verb.test(verbLemma)) return;
      out.push({
        x,
        kind: "word:pronoun-alone",
        english: words[j]!,
        gloss: t[j]!,
        fix: `one group with ${JSON.stringify(before)}: the lemma ${JSON.stringify(verbLemma)} on both, and a u over the run in natural order`,
        why: `${JSON.stringify(target)} can show after the English ${JSON.stringify(before)} before its verb is known`,
      });
    });
  }
  return out;
}
